public static L1WeaponSkillType get() {
		return new W_SK0016();
	}

public double start_weapon_skill(final L1PcInstance pc, final L1Character target, final L1ItemInstance weapon,
			final double srcdmg) {
		try {
			if (mode2(pc,target)) {
				return 0.0D;
			}
			final int ev = weapon.getEnchantLevel();
			if (ev < 0) {
				return 0;
			}
			int random = 0;
			int random2 = 10;

			switch (ev) {
			case 1:
			case 2:
			case 3:
			case 4:
			case 5:
			case 6:
			case 7:
				random = _random1;
				break;
			case 8:
				random = _random1 + 20;
				break;
			case 9:
				random = _random1 + 30;
				random2 = 20;
				break;
			case 10:
				random = _random1 + 50;
				random2 = 20;
				break;
			case 11:
				random = _random1 + 70;
				random2 = 20;
				break;
			default:
				random = _random1 + (ev * 10);
				random2 = 20;
				break;
			}

			switch (_ac_mr) {
			case 1:// 1:防禦
				random -= (target.getAc() * -1) >> 3;// AC / 8
				break;
			case 2:// 2:抗魔
				random -= target.getMr() >> 6;// MR / 8
				break;
			}

			// 疾病術施展機率計算
			final int chance2 = _random.nextInt(1000);
			if (random2 >= chance2) {
				final L1SkillUse l1skilluse = new L1SkillUse();
				l1skilluse.handleCommands(pc, L1SkillId.DISEASE, target.getId(), target.getX(), target.getY(), 0,
						L1SkillUse.TYPE_GMBUFF);
			}

			final int chance = _random.nextInt(1000);
			if (random >= chance) {
				if (mode1(pc,target)) {
					return 0.0D;
				}
				// 【力量+敏捷】*2 +【浮動0-50】
				double damage = ((_random.nextInt(pc.getStr() + pc.getDex()) + 1) * _type1) + +dmg1();

				if (_type3 > 0) {
					damage *= (_type3 / 100D);
				}
				// 輸出動畫
				show(pc, target);

				int outdmg = (int) (dmg2(srcdmg) + dmg3(pc) + damage);
				if ((target.getCurrentHp() - outdmg) < 0) {
					outdmg = 1;
				}
				return calc_dmg(pc, target, outdmg,weapon);
			}
			return 0;

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

