				random2 = 20;
				break;
			case 11:
				random = _random1 + 70;
				random2 = 20;
				break;
			default:
				random = _random1 + (ev * 10);
				random2 = 20;
				break;
			}

			switch (_ac_mr) {
			case 1:// 1:防禦
				random -= (target.getAc() * -1) >> 3;// AC / 8
				break;
			case 2:// 2:抗魔
				random -= target.getMr() >> 6;// MR / 8
				break;
			}

