public static L1WeaponSkillType get() {
		return new W_SK0017();
	}

public double start_weapon_skill(final L1PcInstance pc, final L1Character target, 
			final L1ItemInstance weapon, final double srcdmg) {
		try {
			if (mode2(pc,target)) {
				return 0.0D;
			}
			final int fettersTime = _type3;
			int outdmg = 0 ;
			final int random = random(weapon);
			if ((_random.nextInt(1000) + 1) <= random) {
				if (mode1(pc,target)) {
					return 0.0D;
				}
				L1SpawnUtil.spawnEffect(81182, fettersTime, target.getX(), 
						target.getY(), target.getMapId(), target, 0);
				if (target instanceof L1PcInstance) {
					final L1PcInstance targetPc = (L1PcInstance) target;

					targetPc.setSkillEffect(MOVE_STOP, fettersTime * 1000);
					targetPc.sendPacketsX8(new S_SkillSound(targetPc.getId(), 4184));
					targetPc.sendPackets(new S_Paralysis(S_Paralysis.TYPE_BIND, true));
					show(pc, targetPc);
					if (_type1 != 0) {
						outdmg += _random.nextInt(_type1) + _type2;
					} else {
						outdmg += _type2;
					}
					return calc_dmg(pc, target, outdmg, weapon);
				} else if ((target instanceof L1MonsterInstance) || 
						(target instanceof L1SummonInstance) || 
						(target instanceof L1PetInstance)) {
					final L1NpcInstance npc = (L1NpcInstance) target;
					npc.setSkillEffect(MOVE_STOP, fettersTime * 1000);
					npc.broadcastPacketX8(new S_SkillSound(npc.getId(), 4184));
					npc.setParalyzed(true);
					show(pc, npc);
					if (_type1 != 0) {
						outdmg += _random.nextInt(_type1) + _type2;
					} else {
						outdmg += _type2;
					}
					return calc_dmg(pc, target, outdmg, weapon);
				}

			}
			return 0;
		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

