protected int random(final L1ItemInstance weapon) {
		try {
			int int1 = _random1;
			if (_random2 != 0) {
				if (weapon.getEnchantLevel() > 0) {
					int1 += weapon.getEnchantLevel() * _random2;
				}
			}
			return int1;

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected boolean mode1(L1PcInstance pc, L1Character target) {
		try {
//			if (_c == 1) {// 動畫出現在自己身上
				if (target.hasSkillEffect(31)) {
					target.removeSkillEffect(31);
					int castgfx2 = SkillsTable.get().getTemplate(31).getCastGfx2();
					target.broadcastPacketAll(new S_SkillSound(target.getId(), castgfx2));
					if (target instanceof L1PcInstance) {
						L1PcInstance tgpc = (L1PcInstance) target;
						tgpc.sendPacketsAll(new S_SkillSound(tgpc.getId(), castgfx2));
					}
					return true;
				}
//			}
		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return false;
	}

protected boolean mode2(L1PcInstance pc, L1Character target) {
		try {
		//	if (_c == 2) {// 動畫出現在自己身上
				if (target.hasSkillEffect(31)) {
					target.removeSkillEffect(31);
					int castgfx2 = SkillsTable.get().getTemplate(31).getCastGfx2();
					target.broadcastPacketAll(new S_SkillSound(target.getId(), castgfx2));
					if (target instanceof L1PcInstance) {
						L1PcInstance tgpc = (L1PcInstance) target;
						tgpc.sendPacketsAll(new S_SkillSound(tgpc.getId(), castgfx2));
					}
					return true;
				}
	//		}
		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return false;
	}

protected int dmg1() {
		try {
			if (_srcdmg != 0) {
				final int int1 = _random.nextInt(_srcdmg) + 1;
				return int1;
			}

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected double dmg2(final double srcdmg) {
		try {
			if (_addsrcdmg != 0) {
				final double double1 = (srcdmg * _addsrcdmg) / 100;
				return double1;
			}

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected int dmg3(final L1PcInstance pc) {
		try {
			if (_power > 0) {// （所需角色能力值-5）* leveldmg
				int int1 = 0;
				int tmp = _power;
				int i = 0;
				if (tmp >= 32) {// 32:體
					i += 1;
					tmp -= 32;
					int1 += pc.getCon();
				}
				if (tmp >= 16) {// 16:魅
					i += 1;
					tmp -= 16;
					int1 += pc.getCha();
				}
				if (tmp >= 8) {// 8:精
					i += 1;
					tmp -= 8;
					int1 += pc.getWis();
				}
				if (tmp >= 4) {// 4:智
					i += 1;
					tmp -= 4;
					int1 += pc.getInt();
				}
				if (tmp >= 2) {// 2:敏
					i += 1;
					tmp -= 2;
					int1 += pc.getDex();
				}
				if (tmp >= 1) {// 1:力
					i += 1;
					tmp -= 1;
					int1 += pc.getStr();
				}
				int1 = (int1 / i) >> 1;// (>> 1: 除) (<< 1: 乘)
				return int1;
			}

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected double calc_dmg(final L1PcInstance pc, final L1Character target,
			final double srcdmg) {
		try {
			double dmg = srcdmg;
			switch (_ac_mr) {
			case 0:// 無視
				break;

			case 1:// 防禦
				dmg -= DmgAcMr.calcDefense(target);// 被攻擊者防禦力傷害減低
				break;

			case 2:// 抗魔
				dmg = DmgAcMr.calcMrDefense(pc, target, srcdmg);// 被攻擊者防禦力傷害減低
				break;

			case 3:// 防禦 + 抗魔
				dmg -= DmgAcMr.calcDefense(target);// 被攻擊者防禦力傷害減低
				dmg = DmgAcMr.calcMrDefense(pc, target, srcdmg);// 被攻擊者防禦力傷害減低
				break;
			}

			// 屬性影響
			int resist = 0;
			switch (_attr) {
			case L1Skills.ATTR_EARTH:// 地
				resist = target.getEarth();
				break;

			case L1Skills.ATTR_FIRE:// 火
				resist = target.getFire();
				break;

			case L1Skills.ATTR_WATER:// 水
				resist = target.getWater();
				break;

			case L1Skills.ATTR_WIND:// 風
				resist = target.getWind();
				break;
			}
			if (resist != 0) {
				int resistFloor = (int) (0.32 * Math.abs(resist));
				if (resist >= 0) {
					resistFloor *= 1;
				} else {
					resistFloor *= -1;
				}
				// (>> 1: 除) (<< 1: 乘)
				final double attrDeffence = resistFloor >> 5;// / 32.0
				dmg = (1.0 - attrDeffence) * dmg;
			}
			return dmg * _level;

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected void show(final L1PcInstance pc, final L1Character target) {
		try {
			if (_gfxid1 != 0) {// 第一個出現的動畫 設置為0無作用 這個動畫出現在施展者身上
				if (pc.is_send_weapon_gfxid()) {
					pc.sendPackets(new S_SkillSound(pc.getId(), _gfxid1));// single
				}
				pc.broadcastPacketForWeapon(new S_SkillSound(pc.getId(), _gfxid1));// other
			}

			if (_gfxid2 != 0) {// 第二個出現的動畫 設置為0無作用 這個動畫出現在被攻擊者身上
				target.broadcastPacketForWeapon(new S_SkillSound(target.getId(),
						_gfxid2));
				if (target instanceof L1PcInstance) {
					L1PcInstance targetPc = (L1PcInstance) target;
					if (targetPc.is_send_weapon_gfxid()){
					targetPc.sendPackets(new S_SkillSound(target.getId(),
							_gfxid2));
					}
				}
			}

			if (_gfxid3 != 0) {// 第三個出現的動畫 設置為0無作用 這個動畫由施展者往被攻擊者
				if (pc.is_send_weapon_gfxid()) {
					pc.sendPackets(new S_UseAttackSkill(pc, target.getId(),
							_gfxid3, target.getX(), target.getY(), 0, 0x0a));// single
				}
				pc.broadcastPacketForWeapon(new S_UseAttackSkill(pc, target.getId(),
						_gfxid3, target.getX(), target.getY(), 0, 0x0a));// other
			}

			if (_gfxid4 != 0) {
				if (_gfxid4_count > 0) {
					final WanponSkill wanponSkill = new WanponSkill(pc);
					wanponSkill.start_skill();
				}
			}

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
	}

public void start_skill() {
			PcOtherThreadPool.get().execute(this);
		}

public void run() {
			try {
				final int x = _pc.getX();
				final int y = _pc.getY();
				final int mapId = _pc.getMapId();
				for (int i = 0; i < _gfxid4_count; i++) {
					Thread.sleep(30);
					final int i1 = _random.nextInt(4);
					final int i2 = _random.nextInt(4);

					switch (_random.nextInt(4)) {
					case 0:
						if (_pc.is_send_weapon_gfxid()) {
							_pc.sendPackets(new S_EffectLocation(new L1Location(
									x + i1, y - i2, mapId), _gfxid4));// single
						}
						_pc.broadcastPacketForWeapon(new S_EffectLocation(new L1Location(
								x + i1, y - i2, mapId), _gfxid4));// other
						break;

					case 1:
						if (_pc.is_send_weapon_gfxid()) {
							_pc.sendPackets(new S_EffectLocation(new L1Location(
									x - i1, y + i2, mapId), _gfxid4));// single
						}
						_pc.broadcastPacketForWeapon(new S_EffectLocation(new L1Location(
								x - i1, y + i2, mapId), _gfxid4));// other
						break;

					case 2:
						if (_pc.is_send_weapon_gfxid()) {
							_pc.sendPackets(new S_EffectLocation(new L1Location(
									x + i1, y + i2, mapId), _gfxid4));// single
						}
						_pc.broadcastPacketForWeapon(new S_EffectLocation(new L1Location(
								x + i1, y + i2, mapId), _gfxid4));// other
						break;

					case 3:
						if (_pc.is_send_weapon_gfxid()) {
							_pc.sendPackets(new S_EffectLocation(new L1Location(
									x - i1, y - i2, mapId), _gfxid4));// single
						}
						_pc.broadcastPacketForWeapon(new S_EffectLocation(new L1Location(
								x - i1, y - i2, mapId), _gfxid4));// other
						break;
					}
				}

			} catch (final Exception e) {
				_log.error(e.getLocalizedMessage(), e);
			}
		}

protected int random(L1ItemInstance weapon, L1PcInstance pc) {
		try {
			if (_random2 != 0 && weapon.getEnchantLevel() > 0) {
				return _random1 + weapon.getEnchantLevel() * _random2;
			} else {
				return _random1;
			}
		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

protected double calc_dmg
	(L1PcInstance pc, L1Character target, double srcdmg, L1ItemInstance weapon) {

		if (target.hasSkillEffect(IMMUNE_TO_HARM)) {// 對手身上有聖界效果
			srcdmg /= 2.0D;
		}

		try {
			switch (_ac_mr) {
			case 0:
				break;
			case 1:
				srcdmg -= DmgAcMr.calcDefense(target);
				break;
			case 2:
				srcdmg = DmgAcMr.calcMrDefense(pc, target, srcdmg, weapon);
				break;
			case 3:
				srcdmg -= DmgAcMr.calcDefense(target);
				srcdmg = DmgAcMr.calcMrDefense(pc, target, srcdmg, weapon);
			}

			int resist = 0;
			switch (_attr) {
			case 1:
				resist = target.getEarth();
				break;
			case 2:
				resist = target.getFire();
				break;
			case 4:
				resist = target.getWater();
				break;
			case 8:
				resist = target.getWind();
				break;
			}

			int resistFloor = (int) (0.16 * Math.abs(resist));

			if (resist >= 0) {
				resistFloor *= 1;
			} else {
				resistFloor *= -1;
			}

			double attrDeffence = resistFloor / 32.0;

			srcdmg = (1.0D - attrDeffence) * srcdmg;

			return srcdmg * _level;// 最終傷害係數計算

		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}

		return 0.0D;
	}

