public static double start_weapon_skill(final L1PcInstance pc,
			final L1Character target, final L1ItemInstance weapon,
			final double srcdmg) {
		try {
			if (weapon == null) {
				return 0;
			}

			// 魔法屏障作用中

			final ArrayList<L1WeaponSkillType> list = WeaponSkillPowerTable
					.get().getTemplate(weapon.getItemId());
			if (list != null) {
				final L1WeaponSkillType tmp = list.get(_random.nextInt(list
						.size()));
				if (tmp != null) {
					if (tmp.get_boss_holdout()) {// 技能對BOSS無效
						if (target instanceof L1NpcInstance) {
							final L1NpcInstance npc = (L1NpcInstance) target;
							if (npc.getNpcTemplate().is_boss()) {
								return 0;
							}
						}
					}

					final double dmg = tmp.start_weapon_skill(pc, target,
							weapon, srcdmg);
					if (target.hasSkillEffect(COUNTER_MAGIC)) {
						target.removeSkillEffect(COUNTER_MAGIC);// 移除技能
						final int castgfx = SkillsTable.get()
								.getTemplate(COUNTER_MAGIC).getCastGfx2();
						target.broadcastPacketX8(new S_SkillSound(target.getId(),
								castgfx));
						if (target instanceof L1PcInstance) {
							final L1PcInstance tgpc = (L1PcInstance) target;
							tgpc.sendPacketsX8(new S_SkillSound(tgpc.getId(), castgfx));
						}
						return 0;
					}
					return dmg;
				}
			}
			return 0;

		} catch (final Exception e) {
			_log.error(e.getLocalizedMessage(), e);
		}
		return 0;
	}

